// WeatherClient - generated by API Free from 1 request that worked in "Try it".
// Types come from one response each: widen int to double, or add ?, where the API can answer differently.
//
//   var client = new WeatherClient(new HttpClient(), "your key");
//   var result = await client.GetDayAsync();

using System;
using System.Collections.Generic;
using System.Net.Http;
using System.Net.Http.Json;
using System.Text.Json;
using System.Text.Json.Serialization;
using System.Threading;
using System.Threading.Tasks;

public sealed class WeatherClient
{
    private readonly HttpClient _http;
    private readonly string _apiKey;

    public WeatherClient(HttpClient http, string apiKey)
    {
        _http = http;
        _apiKey = apiKey;
    }

    /// <summary>GET https://a.example/v1/forecast/{city}/days/{days}?units={units}&amp;from={today}&amp;api_key={key}</summary>
    public async Task<GetDayResponse?> GetDayAsync(string city = "New York", int days = 3, string units = "metric", string from = "2026-09-21", CancellationToken ct = default)
    {
        var url = $"https://a.example/v1/forecast/{Uri.EscapeDataString(city)}/days/{days}?units={Uri.EscapeDataString(units)}&from={Uri.EscapeDataString(from)}&api_key={Uri.EscapeDataString(_apiKey)}";
        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.TryAddWithoutValidation("X-Lang", "en");
        using var response = await _http.SendAsync(request, ct);
        response.EnsureSuccessStatusCode();
        return await response.Content.ReadFromJsonAsync<GetDayResponse>(ct);
    }
}

public sealed class GetDayResponse
{
    [JsonPropertyName("t")]
    public int T { get; set; }
}